_REPORT_WIDTH = {"f02_model_comparison_official.png": 5.4, "f01_confusion_matrices.png": 5.4, "f09_crypto_latency.png": 5.0, "f10_pipeline_latency.png": 5.0,
                 "f08_base_paper_comparison.png": 4.6, "f05_per_category.png": 3.6, "f07_synthetic_vs_real.png": 4.2, "f11_paper_protocol_boxplot.png": 4.0,
                 "03_live-scoring.png": 4.4, "06_secure-transfer-verified.png": 4.4}


def _compact_report(out):
    res = []
    skip_next_p = False
    for b in out:
        k = b[0]
        if k == "p" and b[1].startswith("All measurements in this chapter were made on one machine"):
            b = P("All measurements were made on one machine: an Intel Core i5-12500 (6 cores, 12 threads), 15.7 GB of memory, no GPU, Windows 11, shared with other programs, so absolute timings are indicative. "
                  "Every figure and table was produced from stored JSON by the scripts in `scripts/` and `scripts/docs_build/`; nothing was typed in by hand.")
        elif k == "p" and b[1].startswith("Test conditions for detection"):
            b = P("Models used the shipped hyper-parameters and the threshold 0.5 unless stated; no significance test was run, and five seeds (official partition) and ten repetitions (paper protocol) give the spread.")
        elif k == "code" and (b[1].startswith("POST /api/ids/score\n{") or b[1].startswith("POST /api/ids/score   (the normal preset")):
            continue
        elif k == "h3" and b[1].startswith("8.10.3"):
            skip_next_p = True
            continue
        elif k == "p" and b[1].startswith("The API refuses empty text, payloads over 1 MB"):
            continue
        elif k == "b" and b[1][0].startswith("The detection results use one public dataset"):
            b = ("b", [b[1][i] for i in (0, 3, 4, 5)])
        elif k == "tab":
            cap, rows = b[1], b[3]
            if cap.startswith("Data used"):
                rows = rows[:4]
            elif cap.startswith("Stacked model by category"):
                pass
            elif cap.startswith("Stacked model on the official test set (seed 42) at different thresholds"):
                rows = [r for r in rows if r[0] in ("0.10", "0.50", "0.70", "0.90")]
            elif cap.startswith("Median time in milliseconds"):
                rows = [r for r in rows if r[0] in ("1 KB", "100 KB", "5 MB")]
            elif cap.startswith("Detection metrics under the base-paper-style"):
                rows = [r for r in rows if r[0].split(" (")[0] in ("Stacked ensemble", "XGBoost alone", "1D CNN alone", "Random forest")]
            elif cap.startswith("HTTP API latency"):
                rows = [r for r in rows if not r[0].startswith(("GET /api/health", "POST /api/ids/score-batch"))]
            b = ("tab", cap, b[2], rows, b[4], b[5], min(b[6], 9.0))
        elif k == "fig" and os.path.basename(b[1]) in _REPORT_WIDTH:
            b = ("fig", b[1], b[2], _REPORT_WIDTH[os.path.basename(b[1])])
        res.append(b)
    return res
